/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: plan, release, recording, titled, trackTitle
 *   Constants: guard, noTags
 * Tests
 *   - credited names split on " / " only; company-like fragments become label terms and placeholders are dropped
 *   - album tags plan release searches with the artist and label terms, then a release-only search; the file count is never sent
 *   - valid shared identifiers come first and invalid ones are dropped silently
 *   - a submitted link is rejected without queries and nothing usable is rejected as empty
 *   - submitted text that cannot be sent is reported, while tag and folder text is cleaned
 *   - a one-file import plans a recording search with its artist, the fallback and its ISRC
 *   - folder names lose bracketed year and format groups and split once on " - "
 *   - duplicate queries collapse, over-long combinations are dropped and the plan is capped at six
 *   - the plan keeps its fixed order up to the six-query cap
 *   - a submitted album borrows the tag credits, a submitted song uses its ISRC, and the folder trigger ignores tags
 *   - a one-file song prefers the track artist, and one file without a title falls back to its album tag
 *   - normalized fallbacks fold full-width forms and wave dashes, join Sound Track and drop a trailing remaster note, only for tag and folder text
 *   - the cap keeps identifiers and text searches before their fallbacks
 *   - a one-file song plans its normalized title as fallbacks, with the artist first
 *   - file names are not an accepted input
 *   - an existing Album is looked up by its saved title with its first primary Artist name and normalized fallbacks, never a tag title, label or split name
 *   - a review's submitted name is sent as typed with its primary names, as an album or a song
 *   - an unusable Album title plans nothing
 *   - a submitted Artist name credits the name's searches in place of tag or primary names, as typed: never split, dropped as a placeholder, given a label term or respelled; identifier searches keep the tag label
 *   - a submitted Artist name that cannot be sent rejects the plan like the name
 *   - an existing Album's Track-title searches follow every title search and its fallbacks, at most two within the six-query cap, timed by whether those searches name an Artist
 *   - a Track title is credited to the typed Artist name, else the name given with it, never to the credited names, else searched alone when it weighs at least eight
 *   - an unbuildable or duplicate Track-title search is replaced by the next ranked title, an unusable text is passed over, and none is planned without a title search or in an import
 *   - a stored Track-title search is recognized by its basis and string recording, and an unknown timing reads as the stricter one
 * @end-catalog */

import assert from 'node:assert/strict';
import { after, test } from 'node:test';
import {
    cleanFolderName, isCompanyLikeName, isFallbackLookupQuery, isTrackTitleLookupQuery, normalizedLookupTitle, planMetadataLookup, plannableSubmittedArtist, splitCreditedNames,
    trackTitleLookupTiming, type LookupPlanInput
} from '../../src/administration/lookup/lookupQueryPlanner';
import { trackTitleWeight } from '../../src/administration/lookup/lookupTrackTitles';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const noTags = { album: null, albumArtist: null, title: null, artist: null };
const plan = (input: Partial<LookupPlanInput>) => planMetadataLookup({ trigger: 'tags', fileCount: 9, tags: noTags, ...input });
const release = (query: Record<string, unknown>, basis: 'albumText' | 'folder' = 'albumText', fallback = false) =>
    ({ kind: 'musicBrainzReleaseSearch', query, basis, ...(fallback ? { fallback: true } : {}) });
const recording = (query: Record<string, unknown>, fallback = false) => ({ kind: 'musicBrainzRecordingSearch', query, basis: 'songText', ...(fallback ? { fallback: true } : {}) });
/** A ranked Track title as distinctiveTrackTitles gives it, and the search planned from it. */
const titled = (text: string, artist: string | null = null) => ({ text, artist, weight: trackTitleWeight(text) });
const trackTitle = (query: Record<string, unknown>, when: 'noPreselection' | 'noMatchOrPartial') => ({ kind: 'musicBrainzRecordingSearch', query, basis: 'trackTitle', when });

test('credited names split on " / " only; company-like fragments become label terms and placeholders are dropped', () => {
    assert.deepEqual(splitCreditedNames('Mitsukiyo、KARUT、Nor / NEXON Games'), { artists: ['Mitsukiyo、KARUT、Nor'], labels: ['NEXON Games'] });
    assert.deepEqual(splitCreditedNames('Earth, Wind & Fire'), { artists: ['Earth, Wind & Fire'], labels: [] });
    assert.deepEqual(splitCreditedNames('AC/DC'), { artists: ['AC/DC'], labels: [] });
    assert.deepEqual(splitCreditedNames('Various Artists / [unknown] / 株式会社Yostar / Eagles'), { artists: ['Eagles'], labels: ['株式会社Yostar'] });
    for (const company of ['Asylum Records', 'NEXON Games', '株式会社Yostar', 'Sony Music Entertainment', 'Example Co., Ltd.', 'Example K.K.', 'Example GmbH',
        'Example Inc.', 'Example Studios', 'ランティスレコード', 'Example（株）']) assert.equal(isCompanyLikeName(company), true, company);
    for (const artist of ['Eagles', 'Mitsukiyo、KARUT、Nor', 'Earth, Wind & Fire', 'ヰ世界情緒', 'Recordsmith', 'Studiolo']) assert.equal(isCompanyLikeName(artist), false, artist);
});

test('album tags plan release searches with the artist and label terms, then a release-only search; the file count is never sent', () => {
    const credited = { release: 'Blue Archive Original Soundtrack Vol.1', artist: 'Mitsukiyo、KARUT、Nor', label: 'NEXON Games' };
    assert.deepEqual(plan({ tags: { ...noTags, album: 'Blue Archive Original Soundtrack Vol.1', albumArtist: 'Mitsukiyo、KARUT、Nor / NEXON Games' } }), {
        rejected: null, queries: [release(credited), release({ release: 'Blue Archive Original Soundtrack Vol.1' })]
    });
    assert.deepEqual(plan({ tags: { ...noTags, album: 'Hotel California', albumArtist: 'Various Artists', artist: 'Eagles' } }).queries,
        [release({ release: 'Hotel California' })], 'a placeholder never becomes an artist term');
    // The number of selected files is local evidence, never a query term, whatever it is.
    for (const fileCount of [1, 9, 39, 0, 10_000]) {
        const queries = plan({ fileCount, tags: { ...noTags, album: 'Hotel California', albumArtist: 'Eagles' } }).queries;
        assert.deepEqual(queries, [release({ release: 'Hotel California', artist: 'Eagles' }), release({ release: 'Hotel California' })], String(fileCount));
        assert.equal(JSON.stringify(queries).includes('tracks'), false);
    }
    assert.deepEqual([{ fallback: true }, { fallback: 'true' }, {}, null, 'fallback'].map(isFallbackLookupQuery), [true, false, false, false, false]);
});

test('valid shared identifiers come first and invalid ones are dropped silently', () => {
    const result = plan({
        tags: { ...noTags, album: 'Hotel California', albumArtist: 'Eagles / Asylum Records' },
        identifiers: { releaseId: '24AE881F-7CB3-4C43-B80E-70332CD7C50D', barcode: '075596050920', catalogNumber: '7559-60509-2', isrc: 'USEE11300195' }
    });
    assert.deepEqual(result.queries.slice(0, 3), [
        { kind: 'musicBrainzRelease', releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d', basis: 'releaseId' },
        { kind: 'musicBrainzReleaseSearch', query: { barcode: '075596050920' }, basis: 'barcode' },
        { kind: 'musicBrainzReleaseSearch', query: { catno: '7559-60509-2', label: 'Asylum Records' }, basis: 'catalogNumber' }
    ]);
    assert.equal(result.queries.some(query => query.kind === 'musicBrainzIsrc'), false, 'an ISRC is used only for a one-file import');
    const invalid = plan({ tags: { ...noTags, album: 'Hotel California' },
        identifiers: { releaseId: 'not-a-uuid', barcode: '075596050921', catalogNumber: 'https://example.test/', isrc: 'bad' } });
    assert.deepEqual(invalid.queries.map(query => query.basis), ['albumText']);
    assert.equal(JSON.stringify(invalid).includes('075596050921'), false);
});

test('a submitted link is rejected without queries and nothing usable is rejected as empty', () => {
    for (const text of ['https://musicbrainz.org/release/24ae881f-7cb3-4c43-b80e-70332cd7c50d', 'www.example.test', 'javascript:alert(1)']) {
        assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'album', text }, fileCount: 1,
            identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d' } }), { queries: [], rejected: 'url' });
    }
    assert.deepEqual(plan({}), { queries: [], rejected: 'empty' });
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'song', text: '   ' }, fileCount: 1 }), { queries: [], rejected: 'empty' });
    assert.deepEqual(plan({ trigger: 'folder', folderName: '[FLAC 24bit 96kHz]' }), { queries: [], rejected: 'empty' });
});

test('submitted text that cannot be sent is reported, while tag and folder text is cleaned', () => {
    const submitted = (text: string) => planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'album', text }, fileCount: 9,
        identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d' } });
    for (const text of ['Hotel\u200bCalifornia', '\ufeffHotel California', 'Hotel\u0000California', 'Hotel\nCalifornia']) {
        assert.deepEqual(submitted(text), { queries: [], rejected: 'invalidText' }, JSON.stringify(text));
    }
    assert.deepEqual(submitted('x'.repeat(201)), { queries: [], rejected: 'tooLong' });
    assert.deepEqual(plan({ tags: { ...noTags, album: 'Hotel\u200bCalifornia', albumArtist: '\ufeffEagles' } }).queries[0],
        release({ release: 'HotelCalifornia', artist: 'Eagles' }), 'format characters are removed');
    assert.deepEqual(plan({ tags: { ...noTags, album: '\ufeffHotel California\r\n' }, folderName: 'Unrelated Folder' }).queries,
        [release({ release: 'Hotel California' })], 'a cleaned album tag is used rather than the folder');
    assert.deepEqual(plan({ tags: { ...noTags, album: '\ufeff\u200b' }, folderName: 'Eagles\u200b - Hotel California' }).queries.map(query => (query as { query?: unknown }).query),
        [{ artist: 'Eagles', release: 'Hotel California' }, { release: 'Eagles - Hotel California' }], 'an album tag of format characters only is unusable');
    assert.equal(plan({ tags: { ...noTags, album: 'Hotel California' }, identifiers: { catalogNumber: '7559-\u200b60509-2' } }).queries[0].basis, 'catalogNumber');
});

test('a one-file import plans a recording search with its artist, the fallback and its ISRC', () => {
    assert.deepEqual(plan({ fileCount: 1, tags: { ...noTags, title: 'パンドラコール', artist: 'ヰ世界情緒', album: 'パンドラコール' }, identifiers: { isrc: 'JP-Y39-22-00483' } }).queries, [
        { kind: 'musicBrainzIsrc', isrc: 'JPY392200483', basis: 'isrc' },
        { kind: 'musicBrainzRecordingSearch', query: { recording: 'パンドラコール', artist: 'ヰ世界情緒' }, basis: 'songText' },
        { kind: 'musicBrainzRecordingSearch', query: { recording: 'パンドラコール' }, basis: 'songText' }
    ]);
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'song', text: 'Pandora Call' }, fileCount: 3, tags: noTags }).queries,
        [{ kind: 'musicBrainzRecordingSearch', query: { recording: 'Pandora Call' }, basis: 'songText' }]);
});

test('folder names lose bracketed year and format groups and split once on " - "', () => {
    assert.equal(cleanFolderName('Eagles - Hotel California (1976) [FLAC 24bit/96kHz]'), 'Eagles - Hotel California');
    assert.equal(cleanFolderName('Blue Archive OST Vol.1 [WEB] (Hi-Res)'), 'Blue Archive OST Vol.1');
    assert.equal(cleanFolderName('Hotel California (Live) [2017]'), 'Hotel California (Live)');
    assert.equal(cleanFolderName('[CD]'), null);
    assert.equal(cleanFolderName(null), null);
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'Eagles - Hotel California (1976) [MP3 320]' }).queries, [
        release({ artist: 'Eagles', release: 'Hotel California' }, 'folder'), release({ release: 'Eagles - Hotel California' }, 'folder')
    ]);
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'A - B - C' }).queries, [release({ release: 'A - B - C' }, 'folder')]);
    assert.deepEqual(plan({ folderName: 'Eagles - Hotel California' }).queries.map(query => query.basis), ['folder', 'folder'], 'without usable tags the folder name is used');
    assert.deepEqual(plan({ folderName: 'Eagles - Hotel California', tags: { ...noTags, album: 'Hotel California' } }).queries.map(query => query.basis), ['albumText'],
        'a folder name is never sent while usable tags exist');
});

test('duplicate queries collapse, over-long combinations are dropped and the plan is capped at six', () => {
    const result = plan({ tags: { ...noTags, album: 'Hotel California' }, identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d', barcode: '075596050920', catalogNumber: '7559-60509-2' } });
    assert.equal(new Set(result.queries.map(query => JSON.stringify(query))).size, result.queries.length);
    assert.deepEqual(result.queries.map(query => query.basis), ['releaseId', 'barcode', 'catalogNumber', 'albumText']);
    const long = plan({ tags: { ...noTags, album: '-'.repeat(200), albumArtist: '-'.repeat(200) } });
    assert.deepEqual(long.queries, [release({ release: '-'.repeat(200) })]);
    const many = planMetadataLookup({ trigger: 'tags', fileCount: 1, tags: { album: 'A', albumArtist: 'B / C Records', title: 'T', artist: 'B' },
        identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d', barcode: '075596050920', catalogNumber: 'X-1', isrc: 'USEE11300195' } });
    assert.ok(many.queries.length <= 6);
});

test('the plan keeps its fixed order up to the six-query cap', () => {
    const full = planMetadataLookup({ trigger: 'tags', fileCount: 1, tags: { album: 'A', albumArtist: 'B / C Records', title: 'T', artist: 'B' },
        identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d', barcode: '075596050920', catalogNumber: 'X-1', isrc: 'USEE11300195' } });
    assert.deepEqual(full.queries, [
        { kind: 'musicBrainzRelease', releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d', basis: 'releaseId' },
        { kind: 'musicBrainzReleaseSearch', query: { barcode: '075596050920' }, basis: 'barcode' },
        { kind: 'musicBrainzReleaseSearch', query: { catno: 'X-1', label: 'C Records' }, basis: 'catalogNumber' },
        { kind: 'musicBrainzIsrc', isrc: 'USEE11300195', basis: 'isrc' },
        { kind: 'musicBrainzRecordingSearch', query: { recording: 'T', artist: 'B' }, basis: 'songText' },
        { kind: 'musicBrainzRecordingSearch', query: { recording: 'T' }, basis: 'songText' }
    ]);
    assert.equal(full.rejected, null);
});

test('a submitted album borrows the tag credits, a submitted song uses its ISRC, and the folder trigger ignores tags', () => {
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'album', text: ' Hotel  California ' }, fileCount: 9,
        tags: { ...noTags, albumArtist: 'Eagles / Asylum Records' } }).queries, [
        release({ release: 'Hotel California', artist: 'Eagles', label: 'Asylum Records' }), release({ release: 'Hotel California' })
    ]);
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'song', text: 'パンドラコール' }, fileCount: 1, identifiers: { isrc: 'JPY392200483' } }).queries, [
        { kind: 'musicBrainzIsrc', isrc: 'JPY392200483', basis: 'isrc' },
        { kind: 'musicBrainzRecordingSearch', query: { recording: 'パンドラコール' }, basis: 'songText' }
    ]);
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'Eagles - Hotel California', tags: { ...noTags, album: 'Other Album', albumArtist: 'Other Artist' } }).queries, [
        release({ artist: 'Eagles', release: 'Hotel California' }, 'folder'), release({ release: 'Eagles - Hotel California' }, 'folder')
    ]);
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'Various Artists - Hotel California' }).queries,
        [release({ release: 'Various Artists - Hotel California' }, 'folder')], 'a placeholder never becomes the folder artist');
});

test('a one-file song prefers the track artist, and one file without a title falls back to its album tag', () => {
    assert.deepEqual(plan({ fileCount: 1, tags: { ...noTags, title: 'パンドラコール', artist: 'ヰ世界情緒', albumArtist: 'KAMITSUBAKI RECORD' } }).queries[0],
        { kind: 'musicBrainzRecordingSearch', query: { recording: 'パンドラコール', artist: 'ヰ世界情緒' }, basis: 'songText' });
    assert.deepEqual(plan({ fileCount: 1, tags: { ...noTags, album: 'パンドラコール', albumArtist: 'ヰ世界情緒' } }).queries.map(query => query.basis),
        ['albumText', 'albumText']);
    assert.deepEqual(plan({ fileCount: 2, tags: { ...noTags, title: 'パンドラコール', album: 'パンドラコール' } }).queries.map(query => query.kind),
        ['musicBrainzReleaseSearch'], 'several files are looked up as an album, never by one title');
});

test('normalized fallbacks fold full-width forms and wave dashes, join Sound Track and drop a trailing remaster note, only for tag and folder text', () => {
    const tag = 'Blue Archive Original Sound Track Vol.1 ~Longing for the memorable days~';
    const normalized = 'Blue Archive Original Soundtrack Vol.1 ~Longing for the memorable days~';
    for (const [text, expected] of [
        [tag, normalized], ['Blue Archive Original Sound Track \uff36\uff4f\uff4c\uff0e\uff11', 'Blue Archive Original Soundtrack Vol.1'],
        ['Title \u301cSubtitle\u301c', 'Title ~Subtitle~'], ['Title \uff5eSubtitle\uff5e', 'Title ~Subtitle~'], ['Hotel California (2013 Remaster)', 'Hotel California'],
        ['Hotel California - Remastered 2009', 'Hotel California'], ['Hotel California [Remastered]', 'Hotel California'],
        ['Hotel California (2011 Remastered Version)', 'Hotel California'], ['Original Sound-Tracks', 'Original Soundtracks'],
        ['Hotel California', null], ['(Remastered)', null], ['Remastered Hits', null], ['  Hotel   California  ', null], ['', null], [null, null]
    ] as const) assert.equal(normalizedLookupTitle(text), expected, JSON.stringify(text));
    // A pathological run of spaces before a missing remaster note is bounded and cleaned first.
    assert.equal(normalizedLookupTitle(`A${' '.repeat(800)}(`), null);
    // The credited search respelled first, then the bare text respelled.
    assert.deepEqual(plan({ tags: { ...noTags, album: tag, albumArtist: 'ミツキヨ、KARUT、Nor' }, fileCount: 39 }).queries, [
        release({ release: tag, artist: 'ミツキヨ、KARUT、Nor' }), release({ release: tag }),
        release({ release: normalized, artist: 'ミツキヨ、KARUT、Nor' }, 'albumText', true), release({ release: normalized }, 'albumText', true)
    ]);
    assert.deepEqual(plan({ tags: { ...noTags, album: tag, albumArtist: '株式会社Yostar' }, fileCount: 39 }).queries, [
        release({ release: tag, label: '株式会社Yostar' }), release({ release: tag }),
        release({ release: normalized, label: '株式会社Yostar' }, 'albumText', true), release({ release: normalized }, 'albumText', true)
    ]);
    // A folder's "Artist - Album" split is respelled; its whole name, which names no release, is not.
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'Eagles - Hotel California (2013 Remaster) [FLAC]' }).queries, [
        release({ artist: 'Eagles', release: 'Hotel California (2013 Remaster)' }, 'folder'), release({ release: 'Eagles - Hotel California (2013 Remaster)' }, 'folder'),
        release({ artist: 'Eagles', release: 'Hotel California' }, 'folder', true)]);
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'Hotel California (2013 Remaster) [FLAC]' }).queries,
        [release({ release: 'Hotel California (2013 Remaster)' }, 'folder'), release({ release: 'Hotel California' }, 'folder', true)]);
    assert.deepEqual(plan({ trigger: 'folder', folderName: 'Various Artists - Sound Track' }).queries,
        [release({ release: 'Various Artists - Sound Track' }, 'folder'), release({ release: 'Various Artists - Soundtrack' }, 'folder', true)], 'without a split the whole name is respelled');
    // Submitted text is sent as typed: it gets no respelled variant.
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'album', text: 'Hotel California (2013 Remaster)' }, fileCount: 9, tags: noTags }).queries,
        [release({ release: 'Hotel California (2013 Remaster)' })]);
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', submitted: { kind: 'song', text: 'Theme (Remastered 2009)' }, fileCount: 1, tags: noTags }).queries,
        [recording({ recording: 'Theme (Remastered 2009)' })]);
});

test('the cap keeps identifiers and text searches before their fallbacks', () => {
    const tags = { ...noTags, album: 'Blue Archive Original Sound Track Vol.1', albumArtist: 'Mitsukiyo、KARUT、Nor' };
    const capped = plan({ fileCount: 39, tags, identifiers: { releaseId: '8baecda4-f155-40f6-a173-8f6b98cede5b', barcode: '4582579942951', catalogNumber: 'BACD-0001' } });
    assert.deepEqual(capped.queries.map(query => [query.basis, isFallbackLookupQuery(query)]), [['releaseId', false], ['barcode', false], ['catalogNumber', false],
        ['albumText', false], ['albumText', false], ['albumText', true]]);
    assert.deepEqual(capped.queries.slice(1, 3).map(query => (query as { query: unknown }).query), [{ barcode: '4582579942951' }, { catno: 'BACD-0001' }]);
    assert.deepEqual((capped.queries[5] as { query: unknown }).query, { release: 'Blue Archive Original Soundtrack Vol.1', artist: 'Mitsukiyo、KARUT、Nor' });
});

test('a one-file song plans its normalized title as fallbacks, with the artist first', () => {
    assert.deepEqual(plan({ fileCount: 1, tags: { ...noTags, title: 'Hotel California (2013 Remaster)', artist: 'Eagles' } }).queries, [
        recording({ recording: 'Hotel California (2013 Remaster)', artist: 'Eagles' }), recording({ recording: 'Hotel California (2013 Remaster)' }),
        recording({ recording: 'Hotel California', artist: 'Eagles' }, true), recording({ recording: 'Hotel California' }, true)]);
    assert.deepEqual(plan({ fileCount: 1, tags: { ...noTags, title: 'Theme (Remastered)' } }).queries,
        [recording({ recording: 'Theme (Remastered)' }), recording({ recording: 'Theme' }, true)]);
    assert.deepEqual(plan({ fileCount: 1, tags: { ...noTags, title: 'パンドラコール', artist: 'ヰ世界情緒' } }).queries,
        [recording({ recording: 'パンドラコール', artist: 'ヰ世界情緒' }), recording({ recording: 'パンドラコール' })]);
});

test('file names are not an accepted input', () => {
    const input = { trigger: 'tags', fileCount: 1, tags: noTags, fileName: '01 Hotel California.flac' } as LookupPlanInput;
    assert.deepEqual(planMetadataLookup(input), { queries: [], rejected: 'empty' });
});

test('an existing Album is looked up by its saved title with its first primary Artist name and normalized fallbacks, never a tag title, label or split name', () => {
    const catalog = (album: string | null, credited: string[], fileCount = 3) =>
        planMetadataLookup({ trigger: 'catalog', fileCount, tags: { ...noTags, album }, credited });
    // One member or many: always release searches, never a recording search, and the file count is never sent.
    for (const fileCount of [1, 3]) {
        assert.deepEqual(catalog('Hotel California (2013 Remaster)', ['Eagles', 'Don Henley'], fileCount), { rejected: null, queries: [
            release({ release: 'Hotel California (2013 Remaster)', artist: 'Eagles' }), release({ release: 'Hotel California (2013 Remaster)' }),
            release({ release: 'Hotel California', artist: 'Eagles' }, 'albumText', true), release({ release: 'Hotel California' }, 'albumText', true)
        ] }, String(fileCount));
    }
    // A credited list is never split on " / " and a company-like primary stays an artist term: no label term is ever sent.
    assert.deepEqual(catalog('Duets', ['Synthetic / Duo']).queries, [release({ release: 'Duets', artist: 'Synthetic / Duo' }), release({ release: 'Duets' })]);
    assert.deepEqual(catalog('Soundtrack', ['NEXON Games']).queries, [release({ release: 'Soundtrack', artist: 'NEXON Games' }), release({ release: 'Soundtrack' })]);
    // A placeholder primary is dropped; the first usable name is the one sent.
    assert.deepEqual(catalog('Hits', ['Various Artists']).queries, [release({ release: 'Hits' })]);
    assert.deepEqual(catalog('Hits', ['Various Artists', 'Eagles']).queries, [release({ release: 'Hits', artist: 'Eagles' }), release({ release: 'Hits' })]);
    assert.deepEqual(catalog('Hits', []).queries, [release({ release: 'Hits' })]);
    for (const fileCount of [1, 3]) {
        const queries = catalog('Hotel California', ['Asylum Records'], fileCount).queries;
        assert.equal(queries.some(query => query.kind === 'musicBrainzRecordingSearch'), false);
        assert.equal(JSON.stringify(queries).includes('label'), false);
    }
    // A tag title, file names and identifiers are no catalog input, even when given.
    assert.deepEqual(planMetadataLookup({ trigger: 'catalog', fileCount: 1, tags: { album: 'Hits', albumArtist: 'Eagles / Asylum Records', title: 'Take It Easy', artist: 'Eagles' },
        credited: ['Glenn Frey'], folderName: 'Eagles - Hits [FLAC]' }).queries, [release({ release: 'Hits', artist: 'Glenn Frey' }), release({ release: 'Hits' })]);
});

test('a review\'s submitted name is sent as typed with its primary names, as an album or a song', () => {
    const submitted = (kind: 'album' | 'song', text: string, credited: string[]) => planMetadataLookup({ trigger: 'submitted', fileCount: 3, submitted: { kind, text }, credited }).queries;
    assert.deepEqual(submitted('album', 'Hotel California (2013 Remaster)', ['Eagles / Glenn Frey']),
        [release({ release: 'Hotel California (2013 Remaster)', artist: 'Eagles / Glenn Frey' }), release({ release: 'Hotel California (2013 Remaster)' })]);
    assert.deepEqual(submitted('song', 'Take It Easy', ['Various Artists', 'Eagles']), [recording({ recording: 'Take It Easy', artist: 'Eagles' }), recording({ recording: 'Take It Easy' })]);
    assert.deepEqual(submitted('album', 'Hits', []), [release({ release: 'Hits' })]);
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', fileCount: 3, submitted: { kind: 'album', text: 'https://example.test/a' }, credited: ['Eagles'] }), { queries: [], rejected: 'url' });
});

test('an unusable Album title plans nothing', () => {
    for (const album of [null, '', '   ', '\u200b']) {
        assert.deepEqual(planMetadataLookup({ trigger: 'catalog', fileCount: 3, tags: { ...noTags, album }, credited: ['Eagles'] }), { queries: [], rejected: 'empty' }, JSON.stringify(album));
    }
    assert.deepEqual(planMetadataLookup({ trigger: 'catalog', fileCount: 3, credited: ['Eagles'] }), { queries: [], rejected: 'empty' });
});

test('a submitted Artist name credits the name\'s searches in place of tag or primary names, as typed: never split, dropped as a placeholder, given a label term or respelled; identifier searches keep the tag label', () => {
    const typed = (input: Partial<LookupPlanInput> & { submitted: NonNullable<LookupPlanInput['submitted']> }) => planMetadataLookup({ trigger: 'submitted', fileCount: 9, ...input });
    // An import's album: the typed Artist replaces the album-artist tag and its label term; the catalogue-number search keeps the tag label.
    assert.deepEqual(typed({ submitted: { kind: 'album', text: 'Hotel California', artist: ' Eagles  / Asylum Records ' },
        tags: { ...noTags, albumArtist: 'Glenn Frey / Asylum Records' }, identifiers: { catalogNumber: '7559-60509-2' } }), { rejected: null, queries: [
        { kind: 'musicBrainzReleaseSearch', query: { catno: '7559-60509-2', label: 'Asylum Records' }, basis: 'catalogNumber' },
        release({ release: 'Hotel California', artist: 'Eagles / Asylum Records' }), release({ release: 'Hotel California' })
    ] });
    // A one-file import's song: a placeholder-like typed Artist is sent as typed, in place of the artist tag.
    assert.deepEqual(typed({ fileCount: 1, submitted: { kind: 'song', text: 'Typed Song', artist: 'Various Artists' }, tags: { ...noTags, title: 'Tag Title', artist: 'Tag Artist' } }).queries,
        [recording({ recording: 'Typed Song', artist: 'Various Artists' }), recording({ recording: 'Typed Song' })]);
    // A review: the typed Artist replaces the primary names, as an album or a song.
    assert.deepEqual(typed({ submitted: { kind: 'album', text: 'Hotel California', artist: 'Don Henley' }, credited: ['Eagles'] }).queries,
        [release({ release: 'Hotel California', artist: 'Don Henley' }), release({ release: 'Hotel California' })]);
    assert.deepEqual(typed({ submitted: { kind: 'song', text: 'Take It Easy', artist: 'Don Henley' }, credited: ['Eagles'] }).queries,
        [recording({ recording: 'Take It Easy', artist: 'Don Henley' }), recording({ recording: 'Take It Easy' })]);
    // Never respelled: a remaster note stays and no fallback is planned.
    assert.deepEqual(typed({ submitted: { kind: 'album', text: 'Hotel California (2013 Remaster)', artist: 'Eagles' }, tags: { ...noTags, albumArtist: 'Eagles' } }).queries,
        [release({ release: 'Hotel California (2013 Remaster)', artist: 'Eagles' }), release({ release: 'Hotel California (2013 Remaster)' })]);
    // A credited search over the query bound is dropped, and the bare search stays.
    assert.deepEqual(typed({ submitted: { kind: 'album', text: 'a-'.repeat(100), artist: 'b-'.repeat(100) } }).queries, [release({ release: 'a-'.repeat(100) })]);
});

test('a submitted Artist name that cannot be sent rejects the plan like the name', () => {
    const typed = (artist: unknown) => planMetadataLookup({ trigger: 'submitted', fileCount: 9, submitted: { kind: 'album', text: 'Hotel California', artist: artist as string },
        tags: { ...noTags, albumArtist: 'Eagles' }, identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d' } });
    for (const [artist, rejected] of [['https://example.test/a', 'url'], ['www.example.test', 'url'], ['   ', 'empty'], ['', 'empty'], ['x'.repeat(201), 'tooLong'],
        ['Eagles\u200b', 'invalidText'], ['Eagles\u0000', 'invalidText'], [7, 'invalidText']] as const) {
        assert.deepEqual(typed(artist), { queries: [], rejected }, JSON.stringify(artist));
        // A stored Artist name that would reject the plan is never kept for a rerun.
        assert.equal(plannableSubmittedArtist(artist), false, JSON.stringify(artist));
    }
    assert.equal(plannableSubmittedArtist('  Eagles '), true);
});

test('an existing Album\'s Track-title searches follow every title search and its fallbacks, at most two within the six-query cap, timed by whether those searches name an Artist', () => {
    const titles = (artist: string | null) => ['Take It Easy', 'Witchy Woman', 'Peaceful Easy Feeling', 'Desperado', 'Tequila Sunrise'].map(text => titled(text, artist));
    const catalog = (album: string | null, credited: string[], artist: string | null = null) =>
        planMetadataLookup({ trigger: 'catalog', fileCount: 5, tags: { ...noTags, album }, credited, trackTitles: titles(artist) });
    // Four title searches with their fallbacks, then exactly two of the five titles in ranked order, credited to the name given with
    // them (the review gives the primary name).
    assert.deepEqual(catalog('Eagles (2013 Remaster)', ['Eagles'], 'Eagles'), { rejected: null, queries: [
        release({ release: 'Eagles (2013 Remaster)', artist: 'Eagles' }), release({ release: 'Eagles (2013 Remaster)' }),
        release({ release: 'Eagles', artist: 'Eagles' }, 'albumText', true), release({ release: 'Eagles' }, 'albumText', true),
        trackTitle({ recording: 'Take It Easy', artist: 'Eagles' }, 'noMatchOrPartial'), trackTitle({ recording: 'Witchy Woman', artist: 'Eagles' }, 'noMatchOrPartial')
    ] });
    // Without a usable primary Artist name, a placeholder only included, the title searches name none and the titles go alone,
    // sent for any lack of a preselection.
    for (const credited of [[], ['Various Artists'], ['[unknown]', 'Various Artists']]) {
        assert.deepEqual(catalog('Eagles', credited).queries, [release({ release: 'Eagles' }),
            trackTitle({ recording: 'Take It Easy' }, 'noPreselection'), trackTitle({ recording: 'Witchy Woman' }, 'noPreselection')], JSON.stringify(credited));
    }
    // A credited title search dropped over the query bound leaves only the bare one, which names no Artist, so they are timed as
    // without one.
    const long = 'a-'.repeat(100);
    assert.deepEqual(catalog(long, ['b-'.repeat(100)]).queries, [release({ release: long }),
        trackTitle({ recording: 'Take It Easy' }, 'noPreselection'), trackTitle({ recording: 'Witchy Woman' }, 'noPreselection')]);
    // A submitted name with a typed Artist names one; without one, the primary name does.
    const submitted = (kind: 'album' | 'song', artist: string | undefined, credited: string[]) => planMetadataLookup({ trigger: 'submitted', fileCount: 5,
        submitted: { kind, text: 'Synthetic Name', ...(artist ? { artist } : {}) }, credited, trackTitles: titles('Eagles') }).queries.filter(isTrackTitleLookupQuery);
    assert.deepEqual(submitted('album', 'Don Henley', []).map(query => [query.query, query.when]),
        [[{ recording: 'Take It Easy', artist: 'Don Henley' }, 'noMatchOrPartial'], [{ recording: 'Witchy Woman', artist: 'Don Henley' }, 'noMatchOrPartial']]);
    assert.deepEqual(submitted('song', undefined, ['Eagles']).map(query => [query.query, query.when]),
        [[{ recording: 'Take It Easy', artist: 'Eagles' }, 'noMatchOrPartial'], [{ recording: 'Witchy Woman', artist: 'Eagles' }, 'noMatchOrPartial']]);
    assert.deepEqual(submitted('song', undefined, ['Various Artists']).map(query => query.when), ['noPreselection', 'noPreselection']);
    // A plan that already holds six searches has no room left, and one with five keeps a single Track-title search.
    const identified = (identifiers: LookupPlanInput['identifiers']) => planMetadataLookup({ trigger: 'submitted', fileCount: 5, submitted: { kind: 'album', text: 'Eagles' },
        credited: ['Eagles'], identifiers, trackTitles: titles('Eagles') }).queries.filter(isTrackTitleLookupQuery).length;
    assert.equal(identified({ releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d', barcode: '075596050920', catalogNumber: '7559-60509-2' }), 1);
});

test('a Track title is credited to the typed Artist name, else the name given with it, never to the credited names, else searched alone when it weighs at least eight', () => {
    const catalog = (credited: string[], trackTitles: ReturnType<typeof titled>[]) =>
        planMetadataLookup({ trigger: 'catalog', fileCount: 3, tags: { ...noTags, album: 'Hits' }, credited, trackTitles }).queries.filter(isTrackTitleLookupQuery).map(query => query.query);
    // A title keeps the name given with it (the review resolves the member's own, else the Album's, by name and MusicBrainz ID),
    // cleaned; a placeholder given name, or none, goes alone, never credited to the Album's credited names by name only.
    assert.deepEqual(catalog(['Various Artists', 'Eagles'], [titled('Take It Easy', ' Glenn  Frey '), titled('Witchy Woman', 'Various Artists')]),
        [{ recording: 'Take It Easy', artist: 'Glenn Frey' }, { recording: 'Witchy Woman' }]);
    assert.deepEqual(catalog(['Eagles'], [titled('Take It Easy'), titled('Witchy Woman', '[unknown]')]), [{ recording: 'Take It Easy' }, { recording: 'Witchy Woman' }]);
    assert.deepEqual(catalog(['Eagles'], [titled('Home Run')]), []);
    // The typed Artist name wins over both.
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', fileCount: 3, submitted: { kind: 'album', text: 'Hits', artist: 'Don Henley' }, credited: ['Eagles'],
        trackTitles: [titled('Take It Easy', 'Glenn Frey')] }).queries.filter(isTrackTitleLookupQuery).map(query => query.query), [{ recording: 'Take It Easy', artist: 'Don Henley' }]);
    // Without any credit, a title weighing below eight is passed over for the next one; a credited one of any weight is kept.
    assert.equal(trackTitleWeight('Home Run'), 7);
    assert.deepEqual(catalog([], [titled('Home Run'), titled('Lovesong'), titled('Take It Easy')]), [{ recording: 'Lovesong' }, { recording: 'Take It Easy' }]);
    assert.deepEqual(catalog([], [titled('Home Run', 'Synthetic Band')]), [{ recording: 'Home Run', artist: 'Synthetic Band' }]);
    assert.deepEqual(catalog(['Various Artists'], [{ ...titled('Lovesong'), weight: Number.NaN }, titled('Take It Easy')]), [{ recording: 'Take It Easy' }]);
});

test('an unbuildable or duplicate Track-title search is replaced by the next ranked title, an unusable text is passed over, and none is planned without a title search or in an import', () => {
    // A title and Artist over the query bound together, or a search equal to a title search, gives way to the next title.
    const long = 'a-'.repeat(100);
    assert.deepEqual(planMetadataLookup({ trigger: 'catalog', fileCount: 3, tags: { ...noTags, album: 'Hits' }, credited: ['b-'.repeat(100)],
        trackTitles: [titled(long, 'b-'.repeat(100)), titled('Take It Easy'), titled('Witchy Woman')] }).queries.filter(isTrackTitleLookupQuery).map(query => query.query.recording),
        ['Take It Easy', 'Witchy Woman']);
    assert.deepEqual(planMetadataLookup({ trigger: 'submitted', fileCount: 3, submitted: { kind: 'song', text: 'Take It Easy' }, credited: ['Eagles'],
        trackTitles: [titled('Take It Easy'), titled('Take It Easy', 'Eagles'), titled('Witchy Woman', 'Eagles'), titled('Desperado', 'Eagles')] }).queries, [
        recording({ recording: 'Take It Easy', artist: 'Eagles' }), recording({ recording: 'Take It Easy' }),
        trackTitle({ recording: 'Witchy Woman', artist: 'Eagles' }, 'noMatchOrPartial'), trackTitle({ recording: 'Desperado', artist: 'Eagles' }, 'noMatchOrPartial')
    ]);
    // A text that cannot be sent (a link, an empty or over-long text, a malformed entry) is passed over.
    assert.deepEqual(planMetadataLookup({ trigger: 'catalog', fileCount: 3, tags: { ...noTags, album: 'Hits' }, credited: ['Eagles'],
        trackTitles: [titled('https://example.test/a'), titled(''), titled('x'.repeat(201)), null as never, { text: 7 } as never, titled('Desperado')] }).queries
        .filter(isTrackTitleLookupQuery).map(query => query.query.recording), ['Desperado']);
    // No title search, no Track-title search: an unusable Album title still plans nothing.
    for (const album of [null, '', '\u200b']) {
        assert.deepEqual(planMetadataLookup({ trigger: 'catalog', fileCount: 3, tags: { ...noTags, album }, credited: ['Eagles'], trackTitles: [titled('Take It Easy')] }),
            { queries: [], rejected: 'empty' }, JSON.stringify(album));
    }
    // An identifier search is no title search.
    assert.deepEqual(plan({ identifiers: { releaseId: '24ae881f-7cb3-4c43-b80e-70332cd7c50d' }, trackTitles: [titled('Take It Easy')] }).queries.map(query => query.basis), ['releaseId']);
    // Imports never pass titles, so their plans never hold one.
    for (const input of [{ tags: { ...noTags, album: 'Hits', albumArtist: 'Eagles' } }, { fileCount: 1, tags: { ...noTags, title: 'Take It Easy', artist: 'Eagles' } },
        { trigger: 'folder' as const, folderName: 'Eagles - Hits' }, { trigger: 'submitted' as const, submitted: { kind: 'album' as const, text: 'Hits' } }]) {
        assert.equal(plan(input).queries.some(query => query.basis === 'trackTitle'), false, JSON.stringify(input));
    }
});

test('a stored Track-title search is recognized by its basis and string recording, and an unknown timing reads as the stricter one', () => {
    const query = trackTitle({ recording: 'Take It Easy' }, 'noPreselection');
    assert.equal(isTrackTitleLookupQuery(query), true);
    for (const other of [null, 'x', recording({ recording: 'Take It Easy' }), { ...query, kind: 'musicBrainzReleaseSearch' }, { ...query, query: { recording: 7 } }, { ...query, query: null }]) {
        assert.equal(isTrackTitleLookupQuery(other), false, JSON.stringify(other));
    }
    assert.equal(trackTitleLookupTiming(query), 'noPreselection');
    for (const when of ['noMatchOrPartial', 'later', undefined, null]) assert.equal(trackTitleLookupTiming({ ...query, when }), 'noMatchOrPartial', String(when));
    assert.equal(trackTitleLookupTiming(null), 'noMatchOrPartial');
});
